      dfs(r + 1, c, curCap + 1, nextResIndex);
      dfs(r - 1, c, curCap + 1, nextResIndex);
      dfs(r, c + 1, curCap + 1, nextResIndex);
      dfs(r, c - 1, curCap + 1, nextResIndex);
