      extIndex = i;
      break;
    }
  }

  if (extIndex == -1 || extIndex != split.length - 1) {
    return 'Error: Extension not found or misplaced in the filename.';
  }

  final extension = split[extIndex];
  if (extension.length > 3 || extension.length < 1) {
    return 'Error: Invalid extension length.';
  }

  final validExtensions = ['txt', 'jpg', 'png', 'pdf'];
  if (!validExtensions.any((e) => e == extension.toLowerCase())) {
    return 'Error: Unsupported file type.';
  }

  return '';
